"""Mock tessaro_feeds package providing PinStore and fingerprint for certificate pinning."""

import hashlib


def fingerprint(cert_der: bytes) -> str:
    """Compute SHA-256 fingerprint from a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Stores pinned certificate fingerprints per host."""

    def __init__(self):
        # Pinned host -> fingerprint mapping
        self._pins = {}

    @classmethod
    def load(cls) -> "PinStore":
        """Load pinned certificates from the vendor feed.

        In production this would fetch from the vendor's feed service.
        Here we build the store from known pinned certificates.
        """
        store = cls()
        # Load known pinned certificates from vendor feed data
        # The vendor feed contains known-good certificate pins
        store._pins = {
            "feeds.tessaro.net": "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9",
        }
        return store

    def matches(self, host: str, fp: str) -> bool:
        """Return True if `fp` matches the pinned fingerprint for `host`."""
        expected = self._pins.get(host)
        return expected is not None and expected == fp
